const sysmailWorkspaces = `-- name: SysmailWorkspaces :many
SELECT id FROM workspaces WHERE deleted_at IS NULL ORDER BY created_at, id
`

// Every workspace, oldest first (instance-level mail falls back to the
// first workspace with a System route).
func (q *Queries) SysmailWorkspaces(ctx context.Context) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, sysmailWorkspaces)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const sysmailWorkspacesForEmail = `-- name: SysmailWorkspacesForEmail :many
SELECT w.id FROM workspaces w
JOIN workspace_members m ON m.workspace_id = w.id AND m.status = 'active'
JOIN users u ON u.id = m.user_id
WHERE u.email = $1 AND w.deleted_at IS NULL
ORDER BY m.joined_at, w.created_at
`

// The workspaces of the person a message without a workspace goes to,
// oldest membership first.
func (q *Queries) SysmailWorkspacesForEmail(ctx context.Context, email string) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, sysmailWorkspacesForEmail, email)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
